#include <condition_variable>
#include <mutex>
#include <optional>
#include <queue>
#include <utility>

template <typename T>
class BlockingQueue
{
public:
    void push(T value);
    std::optional<T> pop();
    void close();

private:
    std::mutex m_mutex{};
    std::condition_variable m_ready{};
    std::queue<T> m_items{};
    bool m_closed{ false };
};

template <typename T>
void BlockingQueue<T>::push(T value)
{
    {
        const std::lock_guard lock{ m_mutex };
        m_items.push(std::move(value));
    }
    m_ready.notify_one();
}

template <typename T>
std::optional<T> BlockingQueue<T>::pop()
{
    std::unique_lock lock{ m_mutex };
    m_ready.wait(lock, [this] { return !m_items.empty() || m_closed; });
    if (m_items.empty())
    {
        return std::nullopt;
    }
    T value{ std::move(m_items.front()) };
    m_items.pop();
    return value;
}

template <typename T>
void BlockingQueue<T>::close()
{
    {
        const std::lock_guard lock{ m_mutex };
        m_closed = true;
    }
    m_ready.notify_all();
}

