#include <atomic>
#include <thread>
TEST("items come out in order") { BlockingQueue<int> q{}; q.push(1); q.push(2); q.push(3); CHECK(q.pop() == 1); CHECK(q.pop() == 2); CHECK(q.pop() == 3); }
TEST("closing an empty queue ends the wait") { BlockingQueue<int> q{}; std::jthread closer{ [&q] { std::this_thread::sleep_for(std::chrono::milliseconds{ 30 }); q.close(); } }; CHECK(!q.pop().has_value()); }
TEST("items pushed before closing are still delivered") { BlockingQueue<std::string> q{}; q.push("last"); q.close(); CHECK(q.pop() == std::string{ "last" }); CHECK(!q.pop().has_value()); }
TEST("three producers, four consumers, nothing lost or duplicated") {
    BlockingQueue<int> q{};
    std::atomic<long long> sum{ 0 };
    std::atomic<int> received{ 0 };
    {
        std::vector<std::jthread> consumers;
        for (int c{ 0 }; c < 4; ++c) consumers.emplace_back([&] { while (auto item{ q.pop() }) { sum += *item; ++received; } });
        {
            std::vector<std::jthread> producers;
            for (int p{ 0 }; p < 3; ++p) producers.emplace_back([&q, p] { for (int i{ 1 }; i <= 5000; ++i) q.push(p * 100000 + i); });
        }
        q.close();
    }
    CHECK_EQ(received.load(), 15000);
    CHECK_EQ(sum.load(), 3LL * 12502500LL + 5000LL * (0 + 100000 + 200000));
}

